const output = $input.first().json.output;
const modeloUsado = $input.first().json.modelo_usado || 'desconocido';

if (!output || typeof output !== "string" || output.trim().length === 0) {
  throw new Error("El modelo no devolvio un resumen valido (fuente: " + modeloUsado + ")");
}

// Validacion extra: si el resumen no trae la linea de semana esperada,
// se detiene el flujo en vez de guardar basura silenciosamente
// (a diferencia del bug anterior donde esto no frenaba nada).
const semanaMatch = output.match(/SEMANA EPIDEMIOL[OÓ]GICA:\s*(\d{1,2})/i);
if (!semanaMatch) {
  throw new Error("El resumen del modelo no incluye la linea SEMANA EPIDEMIOLOGICA esperada (fuente: " + modeloUsado + ")");
}

return [{
  json: {
    id_boletin: $('Postgres - Obtener pendiente').item.json.id_boletin,
    anio: $('Postgres - Obtener pendiente').item.json.anio,
    semana_epidemiologica: $('Postgres - Obtener pendiente').item.json.semana_epidemiologica,
    resumen: output.trim(),
    procesado: true
  }
}];

