const anio = $json.anio;
const semana = $json.semana_epidemiologica;

// SE 01 DGE = semana domingo-sabado que contiene el 4 de enero
const jan4 = new Date(Date.UTC(anio, 0, 4));
const domSE1 = new Date(jan4);
domSE1.setUTCDate(jan4.getUTCDate() - jan4.getUTCDay()); // 0 = domingo

const dom = new Date(domSE1);
dom.setUTCDate(domSE1.getUTCDate() + (semana - 1) * 7);
const sab = new Date(dom);
sab.setUTCDate(dom.getUTCDate() + 6);

return [{
  json: {
    anio,
    semana_epidemiologica: semana,
    fecha_inicio: dom.toISOString().slice(0, 10),  // domingo
    fecha_fin: sab.toISOString().slice(0, 10)      // sabado
  }
}];

const data = $input.first().json.daily;
const datos = $('Split In Batches (departamentos)').item.json;

if (!data || !data.time) {
  throw new Error('Open-Meteo no devolvio datos para ' + datos.departamento);
}
if (data.time.length !== 7) {
  throw new Error('Se esperaban 7 dias (domingo-sabado DGE), llegaron ' +
    data.time.length + ' para ' + datos.departamento);
}

const promedio = arr => arr.reduce((a, b) => a + b, 0) / arr.length;
const suma = arr => arr.reduce((a, b) => a + b, 0);

const num = (arr) => arr.map(v => v == null ? null : v).filter(v => v !== null);

return [{
  json: {
    latitud: datos.latitud,
    longitud: datos.longitud,
    anio: datos.anio,
    semana_epidemiologica: datos.semana_epidemiologica,
    temp_max_promedio: Number(promedio(num(data.temperature_2m_max)).toFixed(1)),
    temp_min_promedio: Number(promedio(num(data.temperature_2m_min)).toFixed(1)),
    temp_mean_promedio: Number(promedio(num(data.temperature_2m_mean)).toFixed(1)),
    precipitacion_total: Number(suma(num(data.precipitation_sum)).toFixed(1)),
    humedad_promedio: Number(promedio(num(data.relative_humidity_2m_mean)).toFixed(1))
  }
}];
